#[derive(Parser, Debug)]
#[command(name = "lz4")]
#[command(about = "lz4 - Extremely fast compression")]
#[command(version = "*** lz4 v1.10.0 64-bit multithread, by Yann Collet ***")]
struct Args {
    /// Input file (- or stdin for standard input)
    input: Option<String>,

    /// Output file
    output: Option<String>,

    /// Fast compression (default)
    #[arg(short = '1', group = "compression_level")]
    fast: bool,

    /// Slowest compression level
    #[arg(short = '9', group = "compression_level")]
    best: bool,

    /// Ultra-high compression (HC mode)
    #[arg(long, group = "compression_level")]
    best_hc: bool,

    /// Decompression
    #[arg(short = 'd')]
    decompress: bool,

    /// Force write to standard output
    #[arg(short = 'c')]
    stdout: bool,

    /// Preserve source files (default)
    #[arg(short = 'k')]
    keep: bool,

    /// Remove source file after successful compression/decompression
    #[arg(long)]
    rm: bool,

    /// Overwrite output without prompting
    #[arg(short = 'f')]
    force: bool,

    /// Display help
    #[arg(short = 'h')]
    help: bool,

    /// Test compressed file integrity
    #[arg(short = 't')]
    test: bool,

    /// Verbose mode
    #[arg(short = 'v')]
    verbose: bool,

    /// Suppress warnings; specify twice to suppress errors too
    #[arg(short = 'q', action = clap::ArgAction::Count)]
    quiet: u8,

    /// Multiple input files (implies automatic output filenames)
    #[arg(short = 'm')]
    multiple: bool,

    /// Force compression
    #[arg(short = 'z')]
    force_compression: bool,

    /// Use # threads for compression (0 = auto)
    #[arg(short = 'T')]
    threads: Option<usize>,

    /// Recursive mode (directories)
    #[arg(short = 'r')]
    recursive: bool,

    /// Block size (4=64KB, 5=256KB, 6=1MB, 7=4MB)
    #[arg(short = 'B')]
    block_size: Option<String>,

    /// Use FILE as dictionary
    #[arg(short = 'D')]
    dictionary: Option<PathBuf>,

    /// Compress using Legacy format
    #[arg(short = 'l')]
    legacy: bool,

    /// Display version number
    #[arg(short = 'V')]
    version: bool,

    /// Cut file into blocks
    #[arg(long)]
    no_frame_crc: bool,

    /// Include original size
    #[arg(long)]
    content_size: bool,

    /// List information about .lz4 files
    #[arg(long)]
    list: Option<PathBuf>,

    /// Sparse mode
    #[arg(long)]
    sparse: Option<bool>,

    /// No sparse mode
    #[arg(long)]
    no_sparse: bool,

    /// Decompress faster
    #[arg(long)]
    favor_decSpeed: bool,

    /// Ultra fast compression
    #[arg(long)]
    fast_mode: Option<Option<u32>>,

    /// Benchmark file
    #[arg(short = 'b')]
    benchmark: Option<u32>,

    /// Test compression levels
    #[arg(short = 'e')]
    bench_end: Option<u32>,

    /// Minimum evaluation time in seconds
    #[arg(short = 'i')]
    bench_time: Option<u32>,

    /// Block Independence
    #[arg(short = 'I')]
    block_independence: bool,

    /// Block dependency
    #[arg(short = 'D')]
    block_dependency: bool,

    /// Enable block checksum
    #[arg(short = 'X')]
    block_checksum: bool,
}

fn main() -> Result<()> {
    env_logger::init();

    let args = Args::parse();

    // Handle version flag
    if args.version {
        println!("*** lz4 v1.10.0 64-bit multithread, by Yann Collet ***");
        return Ok(());
    }

    // Handle help flag
    if args.help {
        println!("*** lz4 v1.10.0 64-bit multithread, by Yann Collet ***");
        println!("Usage : ");
        println!("      lz4 [arg] [input] [output] ");
        println!();
        println!("input   : a filename");
        println!("          with no FILE, or when FILE is - or stdin, read standard input");
        println!("Arguments :");
        println!(" -1     : fast compression (default)");
        println!(" -12    : slowest compression level");
        println!(" -T#    : use # threads for compression (default:0==auto)");
        println!(" -d     : decompression (default for .lz4 extension)");
        println!(" -f     : overwrite output without prompting");
        println!(" -k     : preserve source files(s)  (default)");
        println!("--rm    : remove source file(s) after successful de/compression");
        println!(" -h/-H  : display help/long help and exit");
        println!();
        println!("Advanced arguments :");
        println!(" -V     : display Version number and exit");
        println!(" -v     : verbose mode");
        println!(" -q     : suppress warnings; specify twice to suppress errors too");
        println!(" -c     : force write to standard output, even if it is the console");
        println!(" -t     : test compressed file integrity");
        println!(" -m     : multiple input files (implies automatic output filenames)");
        println!(" -r     : operate recursively on directories (sets also -m)");
        println!(" -l     : compress using Legacy format (Linux kernel compression)");
        println!(" -z     : force compression");
        println!(" -D FILE: use FILE as dictionary (compression & decompression)");
        println!(" -B#    : cut file into blocks of size # bytes [32+]");
        println!("                     or predefined block size [4-7] (default: 7)");
        println!(" -BI    : Block Independence (default)");
        println!(" -BD    : Block dependency (improves compression ratio)");
        println!(" -BX    : enable block checksum (default:disabled)");
        println!("--no-frame-crc : disable stream checksum (default:enabled)");
        println!("--content-size : compressed frame includes original size (default:not present)");
        println!("--list FILE : lists information about .lz4 files (useful for files compressed with --content-size flag)");
        println!("--[no-]sparse  : sparse mode (default:enabled on file, disabled on stdout)");
        println!("--favor-decSpeed: compressed files decompress faster, but are less compressed");
        println!("--fast[=#]: switch to ultra fast compression level (default: 1)");
        println!("--best  : same as -12");
        println!("Benchmark arguments :");
        println!(" -b#    : benchmark file(s), using # compression level (default : 1)");
        println!(" -e#    : test all compression levels from -bX to # (default : 1)");
        println!(" -i#    : minimum evaluation time in seconds (default : 3s)");
        return Ok(());
    }

    // Determine if we're compressing or decompressing
    let should_decompress = args.decompress || 
        (args.input.as_ref().map(|i| i.ends_with(".lz4")).unwrap_or(false) && !args.force_compression && !args.multiple);

    // Get input and output paths
    let input_path = args.input.clone();
    let output_path = args.output.clone();

    // Handle file operations
    match (input_path, output_path, should_decompress) {
        (Some(input), Some(output), compress_mode) => {
            if args.verbose {
                println!("*** lz4 v1.10.0 64-bit multithread, by Yann Collet ***");
                if let Some(threads) = args.threads {
                    if threads > 0 {
                        println!("Using {} threads for compression", threads);
                    } else {
                        let num_cpus = num_cpus::get();
                        println!("Using {} threads for compression", num_cpus);
                    }
                } else {
                    let num_cpus = num_cpus::get();
                    println!("Using {} threads for compression", num_cpus);
                }
            }

            if args.test {
                // Test integrity
                test_file(&input, args.quiet)?;
            } else if args.multiple {
                // Handle multiple files - not yet implemented
                eprintln!("Multiple files mode not yet implemented");
            } else if !compress_mode {
                // Compress
                compress_file(&input, &output, &args, args.quiet)?;
            } else {
                // Decompress
                decompress_file(&input, &output, &args, args.quiet)?;
            }

            // Remove source file if --rm flag is set
            if args.rm {
                fs::remove_file(&input).with_context(|| format!("Failed to remove source file {}", input))?;
            }
        }
        (Some(input), None, _) => {
            // Only input file provided, auto-generate output
            if args.multiple {
                eprintln!("Multiple files mode not yet implemented");
            } else if should_decompress {
                let output = if input.ends_with(".lz4") {
                    input[..input.len()-4].to_string()
                } else {
                    format!("{}.out", input)
                };
                decompress_file(&input, &output, &args, args.quiet)?;
            } else {
                let output = format!("{}.lz4", input);
                compress_file(&input, &output, &args, args.quiet)?;
            }
        }
        (None, _, _) | (_, Some(_), _) if args.multiple => {
            // Multiple files mode - not yet fully implemented
            eprintln!("Multiple files mode not yet fully implemented");
        }
        _ => {
            eprintln!("Invalid arguments");
            process::exit(1);
        }
    }

    Ok(())
}

fn compress_file(input: &str, output: &str, _args: &Args, _quiet: u8) -> Result<()> {
    // Read input
    let data = if input == "-" || input == "stdin" {
        let mut buf = Vec::new();
        io::stdin().read_to_end(&mut buf)?;
        buf
    } else {
        fs::read(input)?
    };

    if _quiet == 0 {
        eprint!("Read : ");
        eprint_progress(data.len());
    }

    // Compress using lz4
    let mut compressed = Vec::new();
    lz4::block::compress_to_vec(&data, None, false, &mut compressed)
        .context("Compression failed")?;

    if _quiet == 0 {
        let ratio = (compressed.len() as f64 / data.len() as f64) * 100.0;
        eprint!("\r");
        eprintln!("Compressed {} bytes into {} bytes ==> {:.2}%", data.len(), compressed.len(), ratio);
    }

    // Write output
    if output == "-" || output == "stdout" {
        io::stdout().write_all(&compressed)?;
    } else {
        fs::write(output, &compressed)?;
    }

    Ok(())
}

fn decompress_file(input: &str, output: &str, _args: &Args, _quiet: u8) -> Result<()> {
    // Read input
    let data = if input == "-" || input == "stdin" {
        let mut buf = Vec::new();
        io::stdin().read_to_end(&mut buf)?;
        buf
    } else {
        fs::read(input)?
    };

    if _quiet == 0 {
        eprint!("Decompressed : ");
        eprint_progress(0);
    }

    // Decompress using lz4
    let decompressed = lz4::block::decompress(&data)
        .context("Decompression failed")?;

    if _quiet == 0 {
        eprintln!();
        if let Some(input_name) = input.split('/').last() {
            eprintln!("{:<30}: decoded {} bytes", input_name, decompressed.len());
        }
    }

    // Write output
    if output == "-" || output == "stdout" {
        io::stdout().write_all(&decompressed)?;
    } else {
        fs::write(output, &decompressed)?;
    }

    Ok(())
}

fn test_file(input: &str, _quiet: u8) -> Result<()> {
    let data = fs::read(input)?;

    if _quiet == 0 {
        eprint!("Decompressed : ");
        eprint_progress(0);
    }

    match lz4::block::decompress(&data) {
        Ok(decompressed) => {
            if _quiet == 0 {
                eprintln!();
                if let Some(input_name) = input.split('/').last() {
                    eprintln!("{:<30}: decoded {} bytes", input_name, decompressed.len());
                }
            }
            Ok(())
        }
        Err(e) => {
            eprintln!("Error: Failed to decompress {}: {}", input, e);
            Err(anyhow!("Decompression failed"))
        }
    }
}

fn eprint_progress(bytes: usize) {
    let mb = bytes as f64 / (1024.0 * 1024.0);
    eprint!("{:.1} MiB   ==> ", mb);
    // Clear to end of line and move cursor back
    eprint!("\r");
}
