fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() < 2 {
        print_help();
        return;
    }

    let mut input_file: Option<String> = None;
    let mut output_file: Option<String> = None;
    let mut decompress = false;
    let mut verbose = false;
    let mut quiet = 0;
    let mut force = false;
    let mut test_mode = false;
    let mut remove_source = false;
    let mut force_compression = false;
    let mut show_help = false;
    let mut show_version = false;
    let mut stdout_mode = false;

    let mut i = 1;
    while i < args.len() {
        match args[i].as_str() {
            "-h" | "--help" => {
                show_help = true;
            }
            "-H" => {
                print_long_help();
                return;
            }
            "-V" | "--version" => {
                show_version = true;
            }
            "-d" | "--decompress" => {
                decompress = true;
            }
            "-v" | "--verbose" => {
                verbose = true;
            }
            "-q" | "--quiet" => {
                quiet += 1;
            }
            "-f" | "--force" => {
                force = true;
            }
            "-c" => {
                stdout_mode = true;
            }
            "-t" | "--test" => {
                test_mode = true;
            }
            "--rm" => {
                remove_source = true;
            }
            "-k" | "--keep" => {
                // Default behavior
            }
            "-z" => {
                force_compression = true;
            }
            "-m" | "--multiple" => {
                eprintln!("Multiple files mode not yet fully implemented");
                process::exit(1);
            }
            _ => {
                if args[i].starts_with('-') {
                    // Skip unknown options for now
                    if i + 1 < args.len() && !args[i + 1].starts_with('-') {
                        i += 1;
                    }
                } else if input_file.is_none() {
                    input_file = Some(args[i].clone());
                } else if output_file.is_none() {
                    output_file = Some(args[i].clone());
                }
            }
        }
        i += 1;
    }

    if show_version {
        println!("*** lz4 v1.10.0 64-bit multithread, by Yann Collet ***");
        return;
    }

    if show_help {
        print_help();
        return;
    }

    match (input_file, output_file, decompress || force_compression) {
        (Some(input), Some(output), should_decompress) => {
            if verbose {
                println!("*** lz4 v1.10.0 64-bit multithread, by Yann Collet ***");
                println!("Using {} threads for compression", num_cpus::get_fallback());
            }

            if test_mode {
                if let Err(e) = test_file(&input, quiet) {
                    if quiet < 2 {
                        eprintln!("Error: {}", e);
                    }
                    process::exit(1);
                }
            } else if !should_decompress {
                if let Err(e) = compress_file(&input, &output, quiet, stdout_mode) {
                    if quiet < 2 {
                        eprintln!("Error: {}", e);
                    }
                    process::exit(1);
                }
            } else if decompress || input.ends_with(".lz4") {
                if let Err(e) = decompress_file(&input, &output, quiet, stdout_mode) {
                    if quiet < 2 {
                        eprintln!("Error: {}", e);
                    }
                    process::exit(1);
                }
            }

            if remove_source {
                let _ = fs::remove_file(&input);
            }
        }
        (Some(input), None, _) => {
            let output = if decompress || input.ends_with(".lz4") {
                input[..input.len() - 4].to_string()
            } else {
                format!("{}.lz4", input)
            };

            if decompress || input.ends_with(".lz4") {
                if let Err(e) = decompress_file(&input, &output, quiet, stdout_mode) {
                    if quiet < 2 {
                        eprintln!("Error: {}", e);
                    }
                    process::exit(1);
                }
            } else {
                if let Err(e) = compress_file(&input, &output, quiet, stdout_mode) {
                    if quiet < 2 {
                        eprintln!("Error: {}", e);
                    }
                    process::exit(1);
                }
            }

            if remove_source {
                let _ = fs::remove_file(&input);
            }
        }
        _ => {
            eprintln!("Invalid arguments");
            process::exit(1);
        }
    }
}

fn compress_file(input: &str, output: &str, quiet: u8, _stdout_mode: bool) -> Result<(), String> {
    let data = if input == "-" || input == "stdin" {
        let mut buf = Vec::new();
        io::stdin().read_to_end(&mut buf).map_err(|e| e.to_string())?;
        buf
    } else {
        fs::read(input).map_err(|e| e.to_string())?
    };

    if quiet == 0 {
        eprint!("Read : {} MiB   ==> ", data.len() as f64 / (1024.0 * 1024.0));
    }

    let compressed = lz4::compress(&data);
    let ratio = (compressed.len() as f64 / data.len().max(1) as f64) * 100.0;

    if quiet == 0 {
        eprint!("\r");
        eprintln!("Compressed {} bytes into {} bytes ==> {:.2}%", data.len(), compressed.len(), ratio);
    }

    if output == "-" || output == "stdout" {
        io::stdout().write_all(&compressed).map_err(|e| e.to_string())?;
    } else {
        fs::write(output, &compressed).map_err(|e| e.to_string())?;
    }

    Ok(())
}

fn decompress_file(input: &str, output: &str, quiet: u8, _stdout_mode: bool) -> Result<(), String> {
    let data = if input == "-" || input == "stdin" {
        let mut buf = Vec::new();
        io::stdin().read_to_end(&mut buf).map_err(|e| e.to_string())?;
        buf
    } else {
        fs::read(input).map_err(|e| e.to_string())?
    };

    if quiet == 0 {
        eprint!("Decompressed : {} MiB   ==> ", 0.0);
    }

    let decompressed = lz4::decompress(&data)?;

    if quiet == 0 {
        eprint!("\r");
        let input_name = Path::new(input).file_name().unwrap_or_default().to_string_lossy();
        eprintln!("{:<30}: decoded {} bytes", input_name, decompressed.len());
    }

    if output == "-" || output == "stdout" {
        io::stdout().write_all(&decompressed).map_err(|e| e.to_string())?;
    } else {
        fs::write(output, &decompressed).map_err(|e| e.to_string())?;
    }

    Ok(())
}

fn test_file(input: &str, quiet: u8) -> Result<(), String> {
    let data = fs::read(input).map_err(|e| e.to_string())?;

    if quiet == 0 {
        eprint!("Decompressed : {} MiB   ==> ", 0.0);
    }

    let decompressed = lz4::decompress(&data)?;

    if quiet == 0 {
        eprint!("\r");
        let input_name = Path::new(input).file_name().unwrap_or_default().to_string_lossy();
        eprintln!("{:<30}: decoded {} bytes", input_name, decompressed.len());
    }

    Ok(())
}

fn print_help() {
    println!("*** lz4 v1.10.0 64-bit multithread, by Yann Collet ***");
    println!("Usage : ");
    println!("      lz4 [arg] [input] [output] ");
    println!();
    println!("input   : a filename");
    println!("          with no FILE, or when FILE is - or stdin, read standard input");
    println!("Arguments :");
    println!(" -1     : fast compression (default) ");
    println!(" -12    : slowest compression level ");
    println!(" -T#    : use # threads for compression (default:0==auto) ");
    println!(" -d     : decompression (default for .lz4 extension)");
    println!(" -f     : overwrite output without prompting ");
    println!(" -k     : preserve source files(s)  (default) ");
    println!("--rm    : remove source file(s) after successful de/compression ");
    println!(" -h/-H  : display help/long help and exit ");
    println!();
    println!("Advanced arguments :");
    println!(" -V     : display Version number and exit");
    println!(" -v     : verbose mode");
    println!(" -q     : suppress warnings; specify twice to suppress errors too");
    println!(" -c     : force write to standard output, even if it is the console");
    println!(" -t     : test compressed file integrity");
    println!(" -m     : multiple input files (implies automatic output filenames)");
    println!(" -r     : operate recursively on directories (sets also -m) ");
    println!(" -l     : compress using Legacy format (Linux kernel compression)");
    println!(" -z     : force compression ");
    println!(" -D FILE: use FILE as dictionary (compression & decompression)");
    println!(" -B#    : cut file into blocks of size # bytes [32+] ");
    println!("                     or predefined block size [4-7] (default: 7) ");
    println!(" -BI    : Block Independence (default)");
    println!(" -BD    : Block dependency (improves compression ratio)");
    println!(" -BX    : enable block checksum (default:disabled)");
    println!("--no-frame-crc : disable stream checksum (default:enabled)");
    println!("--content-size : compressed frame includes original size (default:not present)");
    println!("--list FILE : lists information about .lz4 files (useful for files compressed with --content-size flag)");
    println!("--[no-]sparse  : sparse mode (default:enabled on file, disabled on stdout)");
    println!("--favor-decSpeed: compressed files decompress faster, but are less compressed");
    println!("--fast[=#]: switch to ultra fast compression level (default: 1)");
    println!("--best  : same as -12");
    println!("Benchmark arguments :");
    println!(" -b#    : benchmark file(s), using # compression level (default : 1) ");
    println!(" -e#    : test all compression levels from -bX to # (default : 1) ");
    println!(" -i#    : minimum evaluation time in seconds (default : 3s) ");
}

fn print_long_help() {
    print_help();
}

mod num_cpus {
    pub fn get_fallback() -> usize {
        std::thread::available_parallelism()
            .map(|n| n.get())
            .unwrap_or(1)
    }
}

