const LZ4_MAGIC_NUMBER: u32 = 0x184D2204;
const LZ4_LEGACY_MAGIC: u32 = 0x184C2102;

mod lz4 {
    use std::io::Write;

    const MINMATCH: usize = 4;
    const MFLIMIT: usize = 12;
    const LASTLITERALS: usize = 5;
    const DICTSIZEBITS: usize = 16;
    const DICTSIZE: usize = 1 << DICTSIZEBITS;
    const HASTTABLEBITS: usize = 16;
    const HASHTABLESIZE: usize = 1 << HASTTABLEBITS;
    const MAX_DISTANCE: usize = (1 << 16) - 1;

    pub fn compress(data: &[u8]) -> Vec<u8> {
        let mut output = Vec::new();

        // Write frame header
        output.extend_from_slice(&LZ4_MAGIC_NUMBER.to_le_bytes());

        // Frame descriptor (simple version)
        let flg = 0x60; // Default: no dict, no checksum
        output.push(flg);

        let bd = 0x70; // Block size 4MB (default)
        output.push(bd);

        // Compress blocks
        let block_size = 256 * 1024;
        let mut offset = 0;

        while offset < data.len() {
            let chunk_size = std::cmp::min(block_size, data.len() - offset);
            let chunk = &data[offset..offset + chunk_size];

            let compressed_chunk = compress_block(chunk);

            // Write block size (uncompressed)
            let is_last = offset + chunk_size >= data.len();
            let block_size_value = if is_last && compressed_chunk.len() >= chunk_size {
                (chunk_size as u32) | 0x80000000
            } else if compressed_chunk.len() < chunk_size {
                compressed_chunk.len() as u32
            } else {
                (chunk_size as u32) | 0x80000000
            };

            output.extend_from_slice(&block_size_value.to_le_bytes());

            if compressed_chunk.len() < chunk_size {
                output.extend_from_slice(&compressed_chunk);
            } else {
                output.extend_from_slice(chunk);
            }

            offset += chunk_size;
        }

        // End mark
        output.extend_from_slice(&0u32.to_le_bytes());

        output
    }

    fn compress_block(data: &[u8]) -> Vec<u8> {
        let mut output = Vec::new();
        let mut pos = 0;
        let mut hash_table: Vec<usize> = vec![0; HASHTABLESIZE];

        while pos < data.len() {
            let mut best_len = 0;
            let mut best_dist = 0;

            if pos + MINMATCH <= data.len() {
                let hash = hash_bytes(&data[pos..std::cmp::min(pos + 4, data.len())]);
                let mut ref_pos = hash_table[hash];

                if ref_pos > 0 && pos - ref_pos < MAX_DISTANCE {
                    let max_len = std::cmp::min(258, data.len() - pos);
                    let mut len = 0;

                    while len < max_len && data[ref_pos + len] == data[pos + len] {
                        len += 1;
                    }

                    if len >= MINMATCH {
                        best_len = len;
                        best_dist = pos - ref_pos;
                    }
                }

                hash_table[hash] = pos;
            }

            if best_len >= MINMATCH {
                output.extend_from_slice(&encode_match(best_len, best_dist).as_slice());
                pos += best_len;
            } else {
                if pos > 0 && output.is_empty() {
                    output.push(data[pos]);
                } else if pos > 0 {
                    let last = output.pop().unwrap_or(0);
                    if last < 0xFF {
                        output.push(last + 1);
                    } else {
                        output.push(0xFF);
                    }
                    output.push(data[pos]);
                } else {
                    output.push(1);
                    output.push(data[pos]);
                }
                pos += 1;
            }
        }

        output
    }

    fn hash_bytes(bytes: &[u8]) -> usize {
        let mut h = 0usize;
        for &b in bytes.iter().take(4) {
            h = h.wrapping_mul(31).wrapping_add(b as usize);
        }
        h & (HASHTABLESIZE - 1)
    }

    fn encode_match(len: usize, dist: usize) -> Vec<u8> {
        let mut result = Vec::new();

        let token = if len < 15 {
            (len as u8 - 4) << 4
        } else {
            0xF0
        };

        result.push(token);

        if len >= 15 {
            let mut l = len - 15;
            while l >= 255 {
                result.push(255);
                l -= 255;
            }
            result.push(l as u8);
        }

        result.push((dist & 0xFF) as u8);
        result.push(((dist >> 8) & 0xFF) as u8);

        result
    }

    pub fn decompress(data: &[u8]) -> Result<Vec<u8>, String> {
        let mut pos = 0;
        let mut output = Vec::new();

        if data.len() < 4 {
            return Err("Invalid LZ4 data".to_string());
        }

        let magic = u32::from_le_bytes([data[0], data[1], data[2], data[3]]);
        pos = 4;

        if magic != LZ4_MAGIC_NUMBER && magic != LZ4_LEGACY_MAGIC {
            return Err(format!("Invalid magic number: {:x}", magic));
        }

        // Skip frame descriptor for simplicity
        if magic == LZ4_MAGIC_NUMBER {
            if pos >= data.len() {
                return Err("Incomplete frame descriptor".to_string());
            }
            let _flg = data[pos];
            pos += 1;

            if pos >= data.len() {
                return Err("Incomplete frame descriptor".to_string());
            }
            let _bd = data[pos];
            pos += 1;
        }

        loop {
            if pos + 4 > data.len() {
                break;
            }

            let block_size_bytes = [data[pos], data[pos + 1], data[pos + 2], data[pos + 3]];
            let block_size_value = u32::from_le_bytes(block_size_bytes);
            pos += 4;

            if block_size_value == 0 {
                break;
            }

            let uncompressed = (block_size_value & 0x7FFFFFFF) as usize;
            let is_compressed = (block_size_value & 0x80000000) == 0;

            if pos + uncompressed > data.len() {
                return Err("Incomplete block".to_string());
            }

            if !is_compressed {
                output.extend_from_slice(&data[pos..pos + uncompressed]);
                pos += uncompressed;
            } else {
                let block_data = &data[pos..pos + uncompressed];
                decompress_block(block_data, &mut output)?;
                pos += uncompressed;
            }
        }

        Ok(output)
    }

    fn decompress_block(data: &[u8], output: &mut Vec<u8>) -> Result<(), String> {
        let mut pos = 0;

        while pos < data.len() {
            let token = data[pos];
            pos += 1;

            let literal_len = (token >> 4) as usize;
            let match_len = (token & 0x0F) as usize + 4;

            let mut lit_len = literal_len;
            if literal_len == 15 {
                loop {
                    if pos >= data.len() {
                        return Err("Incomplete literal length".to_string());
                    }
                    let byte = data[pos] as usize;
                    pos += 1;
                    lit_len += byte;
                    if byte != 255 {
                        break;
                    }
                }
            }

            if pos + lit_len > data.len() {
                return Err("Incomplete literals".to_string());
            }
            output.extend_from_slice(&data[pos..pos + lit_len]);
            pos += lit_len;

            if pos + 2 > data.len() {
                break;
            }

            let dist = (data[pos] as usize) | ((data[pos + 1] as usize) << 8);
            pos += 2;

            if dist == 0 || dist > output.len() {
                return Err(format!("Invalid match distance: {}", dist));
            }

            let mut m_len = match_len;
            if match_len == 19 {
                loop {
                    if pos >= data.len() {
                        return Err("Incomplete match length".to_string());
                    }
                    let byte = data[pos] as usize;
                    pos += 1;
                    m_len += byte;
                    if byte != 255 {
                        break;
                    }
                }
            }

            let src_pos = output.len() - dist;
            for i in 0..m_len {
                output.push(output[src_pos + i]);
            }
        }

        Ok(())
    }

    const LZ4_MAGIC_NUMBER: u32 = 0x184D2204;
    const LZ4_LEGACY_MAGIC: u32 = 0x184C2102;
}

