        let mut pos = 0;

        while pos < data.len() {
            if pos >= data.len() {
                break;
            }

            let token = data[pos];
            pos += 1;

            let literal_len = (token >> 4) as usize;
            let match_len = (token & 0x0F) as usize + 4;

            let mut lit_len = literal_len;
            if literal_len == 15 {
                loop {
                    if pos >= data.len() {
                        return Err("Incomplete literal length".to_string());
                    }
                    let byte = data[pos] as usize;
                    pos += 1;
                    lit_len += byte;
                    if byte != 255 {
                        break;
                    }
                }
            }

            if pos + lit_len > data.len() {
                return Err("Incomplete literals".to_string());
