        eprint!("Read : {} MiB   ==> ", data.len() as f64 / (1024.0 * 1024.0));
    }

    let compressed = lz4::compress(&data);
    let ratio = (compressed.len() as f64 / data.len().max(1) as f64) * 100.0;

    if quiet == 0 {
        eprint!("\r");
        eprintln!("Compressed {} bytes into {} bytes ==> {:.2}%", data.len(), compressed.len(), ratio);
    }

    if output == "-" || output == "stdout" {
        io::stdout().write_all(&compressed).map_err(|e| e.to_string())?;
    } else {
        fs::write(output, &compressed).map_err(|e| e.to_string())?;
    }

    Ok(())
