            // Output literals
            let token = (literal_len << 4) as u8;
            output.push(token);

            if literal_len > 0 {
                output.extend_from_slice(&data[literal_start..literal_start + literal_len]);
            }
        }

        output
    }

    pub fn frame_header() -> Vec<u8> {
        let mut result = Vec::new();

        // Magic
        result.extend_from_slice(&Self::MAGIC_NB.to_le_bytes());

        // FLG - Frame Descriptor
        // Bit 0 = reserved
        // Bit 1 = reserved
        // Bit 2 = reserved
        // Bit 3 = reserved
        // Bit 4 = reserved
        // Bit 5 = Content Checksum flag
        // Bit 6 = Content size flag
        // Bit 7 = Block Checksum flag
        // For simple: 0x60 = 01100000 = no checksums, no content size
        result.push(0x60);

        // BD - Block Descriptor
        // Bits 0-2 = reserved
        // Bits 4-6 = Block Maximum Size (7 = 4MB)
        // Bit 7 = reserved
        // For 4MB blocks: 0x70 = 01110000
        result.push(0x70);

        result
    }

    pub fn frame_trailer() -> Vec<u8> {
        vec![0, 0, 0, 0] // End mark
    }

    pub fn encode_block(data: &[u8]) -> Vec<u8> {
        let mut output = Vec::new();
        let mut literals = Vec::new();
        let mut pos = 0;
        let mut hash_table: Vec<usize> = vec![0; Self::HASHER_BASE];

        while pos < data.len() {
            let mut best_len = 0;
            let mut best_dist = 0;

            // Try to find matching sequences
            if pos + 4 <= data.len() {
                let hash = Self::hash(&data[pos..std::cmp::min(pos + 4, data.len())]);
                let mut ref_pos = hash_table[hash % Self::HASHER_BASE];

                if ref_pos > 0 && pos > ref_pos {
                    let max_dist = std::cmp::min(pos - ref_pos, 65535);
                    let max_len = std::cmp::min(255 + 15, data.len() - pos);

                    let mut match_len = 0;
                    while match_len < max_len && 
                          ref_pos + match_len < pos && 
                          data[ref_pos + match_len] == data[pos + match_len] {
                        match_len += 1;
                    }

                    if match_len >= 4 {
                        best_len = match_len;
                        best_dist = max_dist;
                    }
                }

                hash_table[hash % Self::HASHER_BASE] = pos;
            }

            if best_len >= 4 {
                // Output token
                let lit_len = literals.len();
                let token = ((std::cmp::min(lit_len, 15) as u8) << 4) | std::cmp::min((best_len - 4) as u8, 15);
                output.push(token);

                // Output literal length if needed
                if lit_len > 15 {
                    let mut l = lit_len - 15;
                    while l >= 255 {
                        output.push(255);
                        l -= 255;
                    }
                    output.push(l as u8);
                }

                // Output literals
                output.extend_from_slice(&literals);
                literals.clear();

                // Output match
                output.push((best_dist & 0xFF) as u8);
                output.push(((best_dist >> 8) & 0xFF) as u8);

                // Output match length if needed
                if best_len > 19 {
                    let mut m = best_len - 19;
                    while m >= 255 {
                        output.push(255);
                        m -= 255;
                    }
                    output.push(m as u8);
                }

                pos += best_len;
            } else if pos < data.len() {
                literals.push(data[pos]);
                pos += 1;
            }
        }

        // Output remaining literals
        if !literals.is_empty() {
            let lit_len = literals.len();
            let token = (std::cmp::min(lit_len, 15) as u8) << 4;
            output.push(token);

            if lit_len > 15 {
                let mut l = lit_len - 15;
                while l >= 255 {
                    output.push(255);
                    l -= 255;
                }
                output.push(l as u8);
            }

            output.extend_from_slice(&literals);
        }

        output
    }

    fn hash(data: &[u8]) -> usize {
        if data.len() < 4 {
            return 0;
        }

        let mut h = (data[0] as usize) << 24
                  | (data[1] as usize) << 16
                  | (data[2] as usize) << 8
                  | (data[3] as usize);

        ((h.wrapping_mul(Self::KNUTH as usize)) >> 16) & 0xFFFF
    }
}

pub fn compress(data: &[u8]) -> Vec<u8> {
    let mut result = Vec::new();
    result.extend_from_slice(&Lz4Encoder::frame_header());

    // Process blocks
    let block_size = 256 * 1024; // 256KB blocks
    let mut offset = 0;

    while offset < data.len() {
        let chunk_size = std::cmp::min(block_size, data.len() - offset);
        let chunk = &data[offset..offset + chunk_size];

        let compressed = Lz4Encoder::encode_block(chunk);

        // Write block header
        if compressed.len() < chunk_size {
            // Compressed block
            result.extend_from_slice(&(compressed.len() as u32).to_le_bytes());
            result.extend_from_slice(&compressed);
        } else {
            // Uncompressed block
            result.extend_from_slice(&((chunk_size as u32) | Lz4Encoder::BLOCK_UNCOMPRESSIBLE).to_le_bytes());
            result.extend_from_slice(chunk);
        }

        offset += chunk_size;
    }

    result.extend_from_slice(&Lz4Encoder::frame_trailer());
    result
}

pub fn decompress(data: &[u8]) -> Result<Vec<u8>, String> {
    let mut result = Vec::new();
    let mut pos = 0;

    if data.len() < 4 {
        return Err("Data too short".to_string());
    }

    let magic = u32::from_le_bytes([data[0], data[1], data[2], data[3]]);
    if magic != 0x184D2204 {
        return Err(format!("Invalid magic number: {:x}", magic));
    }
    pos = 4;

    // Skip frame descriptor
    if pos >= data.len() {
        return Err("Missing frame descriptor".to_string());
    }
    let _flg = data[pos];
    pos += 1;

    if pos >= data.len() {
        return Err("Missing block descriptor".to_string());
    }
    let _bd = data[pos];
    pos += 1;

    // Decompress blocks
    loop {
        if pos + 4 > data.len() {
            break;
        }

        let block_size_bytes = [data[pos], data[pos + 1], data[pos + 2], data[pos + 3]];
        let block_size = u32::from_le_bytes(block_size_bytes);
        pos += 4;

        if block_size == 0 {
            break;
        }

        let compressed = (block_size & Lz4Encoder::BLOCK_UNCOMPRESSIBLE) == 0;
        let size = (block_size & !Lz4Encoder::BLOCK_UNCOMPRESSIBLE) as usize;

        if pos + size > data.len() {
            return Err("Block size exceeds data".to_string());
        }

        if compressed {
            decompress_block(&data[pos..pos + size], &mut result)?;
        } else {
            result.extend_from_slice(&data[pos..pos + size]);
        }

        pos += size;
    }

    Ok(result)
}

fn decompress_block(data: &[u8], result: &mut Vec<u8>) -> Result<(), String> {
    let mut pos = 0;

    while pos < data.len() {
        if pos >= data.len() {
            break;
        }

        let token = data[pos];
        pos += 1;

        let lit_len_raw = (token >> 4) as usize;
        let mut lit_len = lit_len_raw;

        if lit_len_raw == 15 {
            loop {
                if pos >= data.len() {
                    return Err("EOF in literal length".to_string());
                }
                let byte = data[pos] as usize;
                pos += 1;
                lit_len += byte;
                if byte != 255 {
                    break;
                }
            }
        }

        if pos + lit_len > data.len() {
            return Err("EOF in literals".to_string());
        }

        result.extend_from_slice(&data[pos..pos + lit_len]);
        pos += lit_len;

        if pos >= data.len() {
            break;
        }

        // Distance
        if pos + 2 > data.len() {
            break;
        }

        let dist = (data[pos] as usize) | ((data[pos + 1] as usize) << 8);
        pos += 2;

        if dist == 0 {
            break;
        }

        let match_len_raw = (token & 0x0F) as usize;
        let mut match_len = match_len_raw + 4;

        if match_len_raw == 15 {
            loop {
                if pos >= data.len() {
                    return Err("EOF in match length".to_string());
                }
                let byte = data[pos] as usize;
                pos += 1;
                match_len += byte;
                if byte != 255 {
                    break;
                }
            }
        }

        if dist > result.len() {
            return Err(format!("Invalid distance {}", dist));
        }

        let src = result.len() - dist;
        for i in 0..match_len {
            result.push(result[src + i]);
        }
    }

    Ok(())
}
