fn compress_file(input: &str, output: &str, quiet: u8) -> Result<(), String> {
    let data = if input == "-" || input == "stdin" {
        let mut buf = Vec::new();
        io::stdin().read_to_end(&mut buf).map_err(|e| e.to_string())?;
        buf
    } else {
        fs::read(input).map_err(|e| e.to_string())?
    };

    if quiet == 0 {
        eprint!("Read : {} MiB   ==> ", data.len() as f64 / (1024.0 * 1024.0));
    }

    let compressed = lz4_impl::compress(&data);
    let ratio = (compressed.len() as f64 / data.len().max(1) as f64) * 100.0;

    if quiet == 0 {
        eprint!("\r");
        eprintln!("Compressed {} bytes into {} bytes ==> {:.2}%", data.len(), compressed.len(), ratio);
    }

    if output == "-" || output == "stdout" {
        io::stdout().write_all(&compressed).map_err(|e| e.to_string())?;
    } else {
        fs::write(output, &compressed).map_err(|e| e.to_string())?;
    }

    Ok(())
}

fn decompress_file(input: &str, output: &str, quiet: u8) -> Result<(), String> {
    let data = if input == "-" || input == "stdin" {
        let mut buf = Vec::new();
        io::stdin().read_to_end(&mut buf).map_err(|e| e.to_string())?;
        buf
    } else {
        fs::read(input).map_err(|e| e.to_string())?
    };

    if quiet == 0 {
        eprint!("Decompressed : {} MiB   ==> ", 0.0);
    }

    let decompressed = lz4_impl::decompress(&data)?;

    if quiet == 0 {
        eprint!("\r");
        let input_name = Path::new(input).file_name().unwrap_or_default().to_string_lossy();
