                if byte != 255 {
                    break;
                }
            }
        }

        // Read literals
        if pos + lit_len > data.len() {
            return Err("EOF in literals".to_string());
        }
        result.extend_from_slice(&data[pos..pos + lit_len]);
        pos += lit_len;

        if pos >= data.len() {
            break;
        }

        // Read match offset
        if pos + 2 > data.len() {
            break;
        }
        let offset = (data[pos] as usize) | ((data[pos + 1] as usize) << 8);
        pos += 2;

        if offset == 0 {
            break;
        }

        // Read extended match length
        let mut match_len = match_len_base + 4;
        if match_len_base == 15 {
            loop {
                if pos >= data.len() {
                    return Err("EOF in match length".to_string());
                }
                let byte = data[pos] as usize;
                pos += 1;
                match_len += byte;
                if byte != 255 {
                    break;
                }
            }
        }

        // Copy match
        if offset > result.len() {
            return Err("Invalid offset".to_string());
        }
        let src = result.len() - offset;
        for i in 0..match_len {
            result.push(result[src + i]);
        }
    }

