cat <<'EOF' > src/main.rs
mod lz4_impl;

use std::fs;
use std::io::{self, Read, Write};
use std::env;
use std::path::Path;
use std::process;

fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() < 2 {
        print_help();
        return;
    }

    let mut input_file: Option<String> = None;
    let mut output_file: Option<String> = None;
    let mut decompress = false;
    let mut _verbose = false;
    let mut quiet = 0;
    let mut _force = false;
    let mut test_mode = false;
    let mut remove_source = false;
    let mut force_compression = false;
    let mut show_help = false;
    let mut show_version = false;
    let mut _stdout_mode = false;

    let mut i = 1;
    while i < args.len() {
        let arg = &args[i];
        match arg.as_str() {
            "-h" | "--help" => {
                show_help = true;
            }
            "-H" => {
                print_long_help();
                return;
            }
            "-V" | "--version" => {
                show_version = true;
            }
            "-d" | "--decompress" => {
                decompress = true;
            }
            "-v" | "--verbose" => {
                _verbose = true;
            }
            "-q" | "--quiet" => {
                quiet += 1;
            }
            "-f" | "--force" => {
                _force = true;
            }
            "-c" => {
                _stdout_mode = true;
            }
            "-t" | "--test" => {
                test_mode = true;
            }
            "--rm" => {
                remove_source = true;
            }
            "-k" | "--keep" => {
                // Default behavior
            }
            "-z" => {
                force_compression = true;
            }
            "-m" | "--multiple" => {
                eprintln!("Multiple files mode not yet fully implemented");
                process::exit(1);
            }
            _ => {
                if arg.starts_with('-') {
                    // Skip unknown options - might have arguments
                    if i + 1 < args.len() && !args[i + 1].starts_with('-') {
                        i += 1;
                    }
                } else if input_file.is_none() {
                    input_file = Some(arg.clone());
                } else if output_file.is_none() {
                    output_file = Some(arg.clone());
                }
            }
        }
        i += 1;
    }

    if show_version {
        println!("*** lz4 v1.10.0 64-bit multithread, by Yann Collet ***");
        return;
    }

    if show_help {
        print_help();
        return;
    }

    match (input_file, output_file) {
        (Some(input), Some(output)) => {
            if !test_mode {
                let should_decompress = decompress || (input.ends_with(".lz4") && !force_compression);

                if should_decompress {
                    if let Err(e) = decompress_file(&input, &output, quiet) {
                        if quiet < 2 {
                            eprintln!("Error: {}", e);
                        }
                        process::exit(1);
                    }
                } else {
                    if let Err(e) = compress_file(&input, &output, quiet) {
                        if quiet < 2 {
                            eprintln!("Error: {}", e);
                        }
                        process::exit(1);
                    }
                }
            } else if let Err(e) = test_file(&input, quiet) {
                if quiet < 2 {
                    eprintln!("Error: {}", e);
                }
                process::exit(1);
            }

            if remove_source && !test_mode {
                let _ = fs::remove_file(&input);
            }
        }
        (Some(input), None) => {
            let should_decompress = decompress || (input.ends_with(".lz4") && !force_compression);
            let output = if should_decompress {
                if input.ends_with(".lz4") && input.len() > 4 {
                    input[..input.len() - 4].to_string()
                } else {
                    format!("{}.out", input)
                }
            } else {
                format!("{}.lz4", input)
            };

            if should_decompress {
                if let Err(e) = decompress_file(&input, &output, quiet) {
                    if quiet < 2 {
                        eprintln!("Error: {}", e);
                    }
                    process::exit(1);
                }
            } else {
                if let Err(e) = compress_file(&input, &output, quiet) {
                    if quiet < 2 {
                        eprintln!("Error: {}", e);
                    }
                    process::exit(1);
                }
            }

            if remove_source {
                let _ = fs::remove_file(&input);
            }
        }
        _ => {
            eprintln!("Invalid arguments");
            process::exit(1);
        }
    }
}

fn compress_file(input: &str, output: &str, quiet: u8) -> Result<(), String> {
    let data = if input == "-" {
        let mut buf = Vec::new();
        io::stdin().read_to_end(&mut buf).map_err(|e| e.to_string())?;
        buf
    } else {
        fs::read(input).map_err(|e| e.to_string())?
    };

    if quiet == 0 {
        eprint!("Read : {} MiB   ==> ", data.len() as f64 / (1024.0 * 1024.0));
    }

    let compressed = lz4_impl::compress(&data);
    let ratio = (compressed.len() as f64 / data.len().max(1) as f64) * 100.0;

    if quiet == 0 {
        eprint!("\r");
        eprintln!("Compressed {} bytes into {} bytes ==> {:.2}%", data.len(), compressed.len(), ratio);
    }

    if output == "-" {
        io::stdout().write_all(&compressed).map_err(|e| e.to_string())?;
    } else {
        fs::write(output, &compressed).map_err(|e| e.to_string())?;
    }

    Ok(())
}

fn decompress_file(input: &str, output: &str, quiet: u8) -> Result<(), String> {
    let data = if input == "-" {
        let mut buf = Vec::new();
        io::stdin().read_to_end(&mut buf).map_err(|e| e.to_string())?;
        buf
    } else {
        fs::read(input).map_err(|e| e.to_string())?
    };

    if quiet == 0 {
        eprint!("Decompressed : 0 MiB   ==> ");
    }

    let decompressed = lz4_impl::decompress(&data)?;

    if quiet == 0 {
